using System.IO;
using System.Text.Json;
using System.Text.Json.Nodes;
// string fileName = "{{FilePath}}";
string fileName = Environment.GetEnvironmentVariable("FilePath");
if (File.Exists(fileName))
{
    string content = File.ReadAllText(fileName);

    var jsonNode = new JsonObject
    {
        ["content"] = content,
        ["timestamp"] = DateTime.UtcNow,
        ["status"] = "Success"
    };
    string jsonString = jsonNode.ToJsonString(new JsonSerializerOptions { WriteIndented = true });
    Environment.SetEnvironmentVariable("FOUND_FILEPATH", jsonString);
    Console.WriteLine(jsonString);
}
else
{
    Console.WriteLine($"Error: File '{fileName}' not found.");
}


using System.IO;
using System.Text.Json;
using System.Text.Json.Nodes;
string foundFilePathContent = Environment.GetEnvironmentVariable("FOUND_FILEPATH");
if (!string.IsNullOrEmpty(foundFilePathContent) )
{
    var jsonNode = new JsonObject
    {
        ["content"] = "Found variable 'FOUND_FILEPATH' with content: ",
        ["timestamp"] = DateTime.UtcNow,
        ["status"] = "Success"
    };
    string jsonString = jsonNode.ToJsonString(new JsonSerializerOptions { WriteIndented = true });
    Console.WriteLine(jsonString);
}
else
{
    var jsonNode = new JsonObject
    {
        ["content"] = "Variable 'FOUND_FILEPATH' not found.",
        ["timestamp"] = DateTime.UtcNow,
        ["status"] = "Success"
    };
    string jsonString = jsonNode.ToJsonString(new JsonSerializerOptions { WriteIndented = true });
    Console.WriteLine(jsonString);
}
